var vrtcal_3pids_already_processed = 0;
var vrtcal_3pids_set_cookie = "vrtcal3rdpartyidsset_tmp=";
var vrtcal_3pids_cDecoded = decodeURIComponent(document.cookie); //to be careful
var vrtcal_3pids_cArr = vrtcal_3pids_cDecoded .split('; ');
vrtcal_3pids_cArr.forEach(val => {
if (val.indexOf(vrtcal_3pids_set_cookie) === 0)
        vrtcal_3pids_already_processed = 1;
});

if(vrtcal_3pids_already_processed == 0){
        (function() {
                var purl = window.location.href;
                var url = '//ads.pubmatic.com/AdServer/js/pwt/158287/12459';
                var profileVersionId = '';
                if(purl.indexOf('pwtv=')>0){
                        var regexp = /pwtv=(.*?)(&|$)/g;
                        var matches = regexp.exec(purl);
                        if(matches.length >= 2 && matches[1].length > 0){
                                profileVersionId = '/'+matches[1];
                        }
                }

                var wtads = document.createElement('script');
                wtads.async = true;
                wtads.type = 'text/javascript';
                wtads.src = url+profileVersionId+'/pwt.js';
                var node = document.getElementsByTagName('script')[0];
                node.parentNode.insertBefore(wtads, node);
        })();


        setTimeout(() => {
                if(typeof IHPWT != "undefined"){
                        str = btoa(JSON.stringify(IHPWT.getUserIds()));

                        if(str != ""){
				var vrt3rdpartysub_url = "https://usync.vrtcal.com/thirdpartyidsync_pm.php"+str+"&vrtcal_userid=vuidv3-fd59b452-cd5b-43dd-b87a-5bd05eef6ea3_1793720675"
                                var vrt3rdpartysub = document.createElement('script');
                                vrt3rdpartysub.async = true;
                                vrt3rdpartysub.type = 'text/javascript';
                                vrt3rdpartysub.src = vrt3rdpartysub_url;
                                var node = document.getElementsByTagName('script')[0];
                                node.parentNode.insertBefore(vrt3rdpartysub, node);

                                var date = new Date();
                                date.setTime(date.getTime() + (365 * 24 * 60 * 60 * 1000));//30 days before refresh
                                var expires = "expires=" + date.toUTCString();
                                document.cookie = "vrtcal3rdpartyidsset_tmp=1;"+expires+";path=/;domain=.vrtcal.com;SameSite=None;Secure";
                        }
                }
        }, 250);
}

if (!String.prototype.replaceAll) {
    String.prototype.replaceAll = function(search, replace) {
        const escapedSearchValue = search.replace(/[.*+\-?^${}()|[\]\\]/g, '\\$&');
        const regex = new RegExp(escapedSearchValue, 'g');
        return this.replace(regex, replace);
    };
}

var syncPixels = "";
var syncIframes = "";

var GDPR_APPLIES = "gdpr=";
var GDPR = "gdpr_consent=";
var US_PRIVACY = "us_privacy=";


var params = location.search.substring(1);
var consentString = "";
var usPrivacy = "";
var gdprAppliesValue = "1";

try {

    var index = params.indexOf(GDPR);
    if (index >= 0) {
        consentString = params.substring(index + GDPR.length).split("&")[0];
    }

    index = params.indexOf(GDPR_APPLIES);
    if (index >= 0) {
        var tmp = params.substring(index + GDPR_APPLIES.length).split("&")[0];
        gdprAppliesValue = (tmp == null || tmp === "" || tmp === "1") ? "1" : "0";
    }

    index = params.indexOf(US_PRIVACY);
    if (index >= 0) {
        usPrivacy = params.substring(index + US_PRIVACY.length).split("&")[0];
    }

} catch (e) {
    console.log("Can't detect gdpr consent string");
}

if (syncPixels) {

    var sync = syncPixels.split(" ");
    if (sync != null) {
        sync.forEach(function(url) {

            url = url.replaceAll("${GDPR}",gdprAppliesValue);
            url = url.replaceAll("${GDPR_STRING}", consentString);
            url = url.replaceAll("${US_PRIVACY}", usPrivacy);

            new Image().src = url;

        });
    }
}

if (syncIframes) {

    var syncF = syncIframes.split(",");
    if (syncF != null) {
        syncF.forEach(function(url) {

            url = url.replaceAll("${GDPR}",gdprAppliesValue);
            url = url.replaceAll("${GDPR_STRING}", consentString);
            url = url.replaceAll("${US_PRIVACY}", usPrivacy);

            var iframe = document.createElement("iframe");
            iframe.src = url;
            iframe.style.display = "none";
            iframe.style.width = "0px";
            iframe.style.height = "0px";
            document.body.appendChild(iframe);

        });
    }
}

